// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font loading handled at module level to prevent flickering
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
const loadBebasNeue = makeLoadFont('BebasNeue');

const { fontFamily: antonFamily } = loadAnton();
const { fontFamily: bebasFamily } = loadBebasNeue();



export type PlayerTitleProps = Record<string, any>;

const PlayerTitle: React.FC<PlayerTitleProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  firstName = "LIONEL",
  lastName = "MESSI",
  topRowText = "ARGENTINA",
  bottomRowText = "CHAMPIONS",
  primaryColor = "#FF5A5F",
  secondaryColor = "#FFFFFF",
  fontSizePrimary = 180, 
  fontSizeSecondary = 60, 
  animationStepRate = 3,
  playerDropShadowOpacity = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const durationInFrames = Math.round(durationInSeconds * fps);

  // Handle transparency safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // STEPPY ANIMATION LOGIC
  const steppedFrame = Math.floor(frame / animationStepRate) * animationStepRate;

  // --- INTRO SPRINGS ---
  const topProgress = spring({
    fps,
    frame: Math.max(0, steppedFrame),
    config: { damping: 13, stiffness: 140 },
  });

  const bottomProgress = spring({
    fps,
    frame: Math.max(0, steppedFrame),
    config: { damping: 13, stiffness: 140 },
  });

  const middleProgress = spring({
    fps,
    frame: Math.max(0, steppedFrame - 18),
    config: { damping: 12, stiffness: 200 },
  });

  // --- OUTRO SPRINGS --- (Staggered exit near the end of the duration)
  const exitMiddleProgress = spring({
    fps,
    frame: Math.max(0, steppedFrame - (durationInFrames - 45)),
    config: { damping: 12, stiffness: 200 },
  });

  const exitBottomProgress = spring({
    fps,
    frame: Math.max(0, steppedFrame - (durationInFrames - 25)),
    config: { damping: 13, stiffness: 140 },
  });

  const exitTopProgress = spring({
    fps,
    frame: Math.max(0, steppedFrame - (durationInFrames - 25)),
    config: { damping: 13, stiffness: 140 },
  });

  // --- TRANSFORMATIONS & OPACITIES ---
  // Substantially reduced movement distances + combined with fade in/out
  const moveDist = 100;

  const topX = interpolate(topProgress, [0, 1], [-moveDist, 0]) + interpolate(exitTopProgress, [0, 1], [0, -moveDist]);
  const bottomX = interpolate(bottomProgress, [0, 1], [moveDist, 0]) + interpolate(exitBottomProgress, [0, 1], [0, moveDist]);
  
  // Combine enter and exit progress safely between 0 and 1 for opacities
  const topOpacity = Math.max(0, Math.min(1, topProgress - exitTopProgress));
  const bottomOpacity = Math.max(0, Math.min(1, bottomProgress - exitBottomProgress));
  const middleOpacity = Math.max(0, Math.min(1, middleProgress - exitMiddleProgress));

  // Scale in from 0.8 to 1 (less movement), then scale down to 0.8 on exit
  const middleScale = interpolate(middleProgress, [0, 1], [0.8, 1]) - interpolate(exitMiddleProgress, [0, 1], [0, 0.2]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Lower thirds wrapper - Aligned to bottom left */}
      <div style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        position: "absolute",
        bottom: "10%",
        left: "8%",
      }}>
          
        {/* Country (Top) */}
        <div style={{
          fontFamily: antonFamily,
          fontSize: fontSizePrimary,
          color: primaryColor,
          lineHeight: 0.82,
          textTransform: "uppercase",
          letterSpacing: "-0.03em",
          whiteSpace: "nowrap",
          transform: `translateX(${topX}px)`,
          opacity: topOpacity,
          transition: "none",
          textAlign: "left",
        }}>
          {topRowText}
        </div>

        {/* Country (Bottom) */}
        <div style={{
          fontFamily: antonFamily,
          fontSize: fontSizePrimary,
          color: primaryColor,
          lineHeight: 0.82,
          textTransform: "uppercase",
          letterSpacing: "-0.03em",
          whiteSpace: "nowrap",
          transform: `translateX(${bottomX}px)`,
          opacity: bottomOpacity,
          transition: "none",
          textAlign: "left",
        }}>
          {bottomRowText}
        </div>

        {/* Player Name (Secondary Text Overlay) */}
        <div style={{
          position: "absolute",
          top: "50%",
          left: "50%", 
          transform: `translate(-50%, -50%) scale(${middleScale})`,
          opacity: middleOpacity,
          fontFamily: bebasFamily,
          fontSize: fontSizeSecondary,
          color: secondaryColor,
          textTransform: "uppercase",
          letterSpacing: "0.1em",
          whiteSpace: "nowrap",
          transition: "none",
          zIndex: 10,
          textShadow: `0px 8px 16px rgba(0,0,0,${playerDropShadowOpacity})`
        }}>
          {firstName} {lastName}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default PlayerTitle;